import re,os
for root,_,fs in os.walk('AlgebraicJacobian'):
    for f in sorted(fs):
        if not f.endswith('.lean'): continue
        p=os.path.join(root,f)
        src=open(p).read()
        ms=list(re.finditer(r'^(?:private |protected |@\[simp\]\n)*(theorem|lemma|noncomputable def|def|abbrev)\s+([^\s({\[]+)', src, re.M))
        for idx,m in enumerate(ms):
            start=m.start()
            end=ms[idx+1].start() if idx+1<len(ms) else len(src)
            body=src[start:end]
            stmt=body.split(':=')[0].split(' by\n')[0]
            if 'divFamEps' in stmt:
                print(f"{p}:{src[:start].count(chr(10))+1}  {m.group(2)}")
EOF
